import csv
import re
import sys
from datetime import date
from decimal import Decimal


class TallyError(Exception):
    pass


def parse_amount(text):
    match = re.fullmatch(r'(\()?(\d+\.\d{2})(?(1)\))', text)
    if match is None:
        raise ValueError(f'invalid amount: {text!r}')
    value = Decimal(match.group(2))
    return -value if match.group(1) else value


def tally(paths):
    totals = {}
    for path in paths:
        try:
            handle = open(path, encoding='utf-8-sig', newline='')
        except OSError as exc:
            raise TallyError(f'{path}: {exc.strerror}') from exc
        with handle:
            reader = csv.reader(handle)
            try:
                next(reader, None)
                for row in reader:
                    if not row:
                        continue
                    try:
                        if len(row) != 3:
                            raise ValueError(f'expected 3 columns, got {len(row)}')
                        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', row[0]) is None:
                            raise ValueError(f'invalid date: {row[0]!r}')
                        date.fromisoformat(row[0])
                        amount = parse_amount(row[2])
                    except ValueError as exc:
                        raise TallyError(f'{path}:{reader.line_num}: {exc}') from exc
                    key = row[0][:7]
                    totals[key] = totals.get(key, Decimal(0)) + amount
            except (UnicodeDecodeError, csv.Error) as exc:
                raise TallyError(f'{path}:{reader.line_num + 1}: {exc}') from exc
    return totals


def format_total(total):
    if total == 0:
        total = Decimal(0)
    return f'{total:.2f}'


def main(argv):
    if not argv:
        print('usage: python3 tally.py FILE [FILE ...]', file=sys.stderr)
        return 2
    try:
        totals = tally(argv)
    except TallyError as exc:
        print(f'tally: {exc}', file=sys.stderr)
        return 1
    for month in sorted(totals):
        print(f'{month} {format_total(totals[month])}')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
